import pathlib,json,importlib.util,os,datetime,collections,subprocess
P=pathlib.Path;R=P('/root/data/dtc_l2_mlp_exploration_20261027_v1');G=1024**3
def read(p):return json.loads(P(p).read_bytes())
def load(n,p):s=importlib.util.spec_from_file_location(n,p);m=importlib.util.module_from_spec(s);s.loader.exec_module(m);return m
eng=load('status_l2_native',R/'tools/l2_native.py');q=eng.registered()[2];reference=eng.canonical(next(iter(q['consumed'])));res=eng.resources(reference,True);own=res['own_ram_forecasts'];claims=read(R/'control/POOL_DISPATCH_RESERVATIONS.json')['claims'];mem={line.split()[0]:int(line.split()[1])*1024 for line in P('/proc/meminfo').read_text().splitlines()if line.startswith(('MemAvailable:','MemTotal:'))};unobserved=[r for r in own if r['kind']!='LIVE_MODEL'];running=[r for r in own if r['kind']=='LIVE_MODEL'];history=read(R/'control/HISTORICAL_RSS.json');pred=load('status_resources',R/'tools/l2_resources.py');matrix=read(R/'control/MATRIX_CURRENT.json');first={}
for p in matrix['points']:
 if p['cohort']not in q['admitted_specs']or p['cohort']in q['consumed']:continue
 s=eng.canonical(p['cohort']);f=pred.forecast(s,history)
 if p['program']not in first or p['cell']=='DH'and p['profile']=='P0':first[p['program']]=dict(program=p['program'],cohort=p['cohort'],predicted_GiB=max(s['estimated_peak_model_RAM_bytes'],f['predicted_peak_RAM_bytes'])/G)
