d=dict(CST=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat(),new_spent=len(q['consumed']),new_unspent=q['remaining'],actual_own_live=len(running),own_claim_count=len(claims),preexec_or_uncertain_count=len(unobserved),host_available_GiB=mem['MemAvailable:']/G,host_total_GiB=mem['MemTotal:']/G,cgroup_memory_current_GiB=res['cgroup_memory_current']/G,cgroup_memory_max_GiB=int(res['cgroup_memory_max'])/G,cgroup_clean_reclaimable_credit_GiB=res['cgroup_reclaimable_clean_inactive_file_credit_bytes']/G,cgroup_effective_headroom_GiB=res['cgroup_effective_headroom_bytes']/G,safe_additional_growth_budget_GiB=res['admission_decision']['admission_RAM_budget_bytes']/G,committed_future_growth_GiB=res['total_projected_additional_RAM_bytes']/G,own_future_growth_GiB=sum(r['additional_reserved_bytes']for r in own)/G,own_observed_RSS_sum_GiB=sum(r['RSS_bytes']for r in own)/G,nonlive_future_growth_GiB=sum(r['additional_reserved_bytes']for r in unobserved)/G,peer_future_growth_GiB=(res['total_projected_additional_RAM_bytes']-sum(r['additional_reserved_bytes']for r in own))/G,slack_GiB=(res['admission_decision']['admission_RAM_budget_bytes']-res['total_projected_additional_RAM_bytes'])/G,physical_RAM_pass=res['physical_RAM_pass'],physical_disk_pass=res['physical_disk_pass'],native_free_GiB=res['native_free_bytes']/G,required_disk_free_GiB=res['required_free_bytes']/G,pressure_reasons=res['admission_decision']['pressure_reasons'],cgroup_memory_events=res['cgroup_memory_events'],cpu_quota=res['cpu_quota_equivalent'],source_resource_policy=str(R/'control/RESOURCE_POLICY.json'),largest_unstarted_input_candidates=top,own_growth_top12=sorted([dict(cohort=r['cohort'],RSS_GiB=r['RSS_bytes']/G,future_growth_GiB=r['additional_reserved_bytes']/G,kind=r['kind'])for r in own],key=lambda r:-r['future_growth_GiB'])[:12])
